static FAR struct xhci_dev_s *
xhci_dev_from_hport(FAR struct usbhost_xhci_s *priv,
                    FAR struct usbhost_hubport_s *hport)
{
  uint8_t i;

  for (i = 0; i < priv->no_slots; i++)
    {
      if (priv->devs[i].state != XHCI_SLOT_DISABLED &&
          priv->devs[i].hport == hport)
        {
          return &priv->devs[i];
        }
    }

  return NULL;
}

