       * driver has not reported the descriptor.
       */

      return OK;
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
    }

  /* Only the slot context changes, and it must go in carrying everything
   * the controller already holds, so start from the output context it has
   * been maintaining.
