  /* Initialize device data */

  ret = xhci_device_init(priv, rhport, &rhport->hport.hport,
                         &rhport->ep0);
  if (ret < 0)
    {
      uerr("Failed to initialize device %d\n", ret);
      return ret;
    }

  return OK;
}

