static int xhci_device_init(FAR struct usbhost_xhci_s *priv,
                            FAR struct xhci_rhport_s *rhport,
                            FAR struct usbhost_hubport_s *hport,
                            FAR struct xhci_epinfo_s *ep0info)
{
  FAR struct xhci_dev_s *dev;
  uint8_t                slot;
