import ssl
import time
import uuid

C = Path('E:/openvela/VelaVision')
source = C / 'private/photo-upload-spool/k7-000000004f7e92ac-2'
out = C / 'private/cloud-three-view-report-contract-20261029-r1'
out.mkdir(exist_ok=False)
session = json.loads((C / 'private/cloud-business-live-login-20261029-r1/authenticated-session.json').read_bytes())
assert session['origin'] == 'https://eveaisia.com/openvela'
token = session['response']['data']['sessionToken']
assert isinstance(token, str) and token
old_manifest = json.loads((source / 'submission.json').read_bytes())
names = ('front', 'left', 'right')
files = {}
for name in names:
    raw = (source / (name + '.jpg')).read_bytes()
    assert raw.startswith(b'\xff\xd8') and raw.endswith(b'\xff\xd9')
    assert 0 < len(raw) <= 10 * 1024 * 1024
    assert len(raw) == old_manifest['views'][name]['bytes']
    assert hashlib.sha256(raw).hexdigest() == old_manifest['views'][name]['sha256']
    files[name] = raw
assert len({hashlib.sha256(raw).hexdigest() for raw in files.values()}) == 3
capture = 'cloud-contract-' + uuid.uuid4().hex
boundary = 'VelaVision' + uuid.uuid4().hex
metadata = {'photoVersion': '1', 'captureSessionId': capture, 'consentEvidenceRef': 'dev-consent'}
parts = [('--' + boundary + '\r\nContent-Disposition: form-data; name="metadata"\r\n'
          'Content-Type: application/json\r\n\r\n').encode(),
         json.dumps(metadata, separators=(',', ':')).encode(), b'\r\n']
for name in names:
    parts += [('--' + boundary + '\r\nContent-Disposition: form-data; name="' + name +
               '"; filename="' + name + '.jpg"\r\nContent-Type: image/jpeg\r\n\r\n').encode(),
              files[name], b'\r\n']
parts += [('--' + boundary + '--\r\n').encode()]
body = b''.join(parts)
ctx = ssl.create_default_context()
ctx.minimum_version = ssl.TLSVersion.TLSv1_2
ctx.maximum_version = ssl.TLSVersion.TLSv1_2
start = time.monotonic()
deadline = start + 30
report = {'utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
          'measurement_host': 'Windows PC', 'device_measurement': False,
          'photo_scope': 'Three distinct historical board-captured JPEGs from 2026-10-14; not current camera capture',
          'source_manifest': str(source / 'submission.json'), 'metadata': metadata,
          'idempotency_key': capture, 'images': old_manifest['views'],
          'POST_attempts': 0, 'automatic_POST_retries': 0, 'events': [],
          'board_storage_written': False}

def save(path, obj):
    with path.open('xb') as stream:
        stream.write((json.dumps(obj, ensure_ascii=False, indent=2) + '\n').encode())
        stream.flush()
        os.fsync(stream.fileno())

def redacted(obj):
    if isinstance(obj, dict):
        return {k: '[REDACTED]' if 'token' in k.lower() or k.lower() in ('credential', 'proof', 'authorization')
                else redacted(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [redacted(v) for v in obj]
    return obj

def request(method, path, payload=None, extra=None):
    left = deadline - time.monotonic()
    assert left > 0, 'Total request budget exhausted'
    conn = http.client.HTTPSConnection('eveaisia.com', 443, timeout=min(8, left), context=ctx)
    headers = {'Authorization': 'Bearer ' + token, 'Accept': 'application/json'}
    headers.update(extra or {})
    began = time.monotonic()
    event = {'method': method, 'path': path}
    report['events'].append(event)
    try:
        conn.request(method, path, body=payload, headers=headers)
        response = conn.getresponse()
        raw = response.read(65537)
        assert len(raw) <= 65536, 'Response exceeded fixed bound'
        value = json.loads(raw)
        event.update(http_status=response.status, elapsed_ms=round((time.monotonic() - began) * 1000, 3),
                     response=redacted(value))
        return response.status, value
    finally:
        conn.close()

def identity(value):
    assert isinstance(value, str) and str(uuid.UUID(value)) == value, 'Noncanonical task/report identity'
    return value

save(out / 'upload-intent.json', {k: v for k, v in report.items() if k != 'events'})
try:
    report['POST_attempts'] += 1
    status, response = request('POST', '/openvela/api/v1/skin-assessment-tasks', body,
                               {'Content-Type': 'multipart/form-data; boundary=' + boundary,
                                'Idempotency-Key': capture})
    assert status == 202, 'Upload did not return202; no automatic replay'
    data = response['data']
    task = identity(data['taskId'])
    assert data['status'] == 'queued' and data['photoVersion'] == '1'
    report.update(upload_accepted=True, taskId=task, JPEG_count=3)
    ready = None
    for attempt in range(12):
        status, current = request('GET', '/openvela/api/v1/skin-assessment-tasks/' + task)
        assert status == 200
        data = current['data']
        assert data['taskId'] == task
        if data['status'] == 'report_ready':
            ready = identity(data['reportId'])
            break
        assert data['status'] in ('queued', 'analyzing'), 'Task reached a non-success terminal state'
        time.sleep(min(1, max(0, deadline - time.monotonic())))
    assert ready, 'Report was not ready within bounded polls'
    status, brief = request('GET', '/openvela/api/v1/skin-reports/' + ready + '?view=brief')
    assert status == 200 and brief['data']['reportId'] == ready
    assert all(isinstance(brief['data'].get(k), str) and brief['data'][k] for k in ('conclusion', 'description'))
    save(out / 'report-brief.json', brief)
    status, check = request('GET', '/openvela/api/v1/skin-assessment-tasks/' + task)
    assert status == 200 and check['data']['taskId'] == task and check['data']['reportId'] == ready
    assert check['data']['status'] == 'report_ready'
    report.update(status='upload_and_report_passed', reportId=ready, report_text_received=True,
                  brief_has_view='view' in brief['data'],
                  report_characters=len(brief['data']['conclusion']) + len(brief['data']['description']))
except Exception as error:
    report.update(status='failed', error_type=type(error).__name__, error=str(error)[:250])
report['total_ms'] = round((time.monotonic() - start) * 1000, 3)
save(out / 'result.json', report)
summary = {k: v for k, v in report.items() if k not in ('events', 'images', 'source_manifest')}
