+/* Offline experiment only: no production include or firmware integration.
+ * This is a restricted greeting grammar, NOT device-directed speech detection.
+ * Caller must keep STOP priority and apply only while asleep. */
+#ifndef EXPERIMENTAL_WAKE_ENVELOPE_H
+#define EXPERIMENTAL_WAKE_ENVELOPE_H
+#include "device_voice_intent.h"
+#include <string.h>
+static int experimental_wake_envelope(const char *text, size_t bytes,
+                                      bool verified, bool completed)
+{
+  if (k7_voice_completed_text(text, bytes, verified, completed) != K7_VOICE_TRACK)
+    return 0;
+  char normalized[64]; size_t used = 0;
+  for (size_t i = 0; i < bytes;)
+    {
+      unsigned char c = (unsigned char)text[i];
+      if (c == ' ' || c == '\t' || c == '\r' || c == '\n' ||
+          c == ',' || c == '.' || c == '!' || c == '?') { i++; continue; }
+      const char *marks[] = {"，", "。", "！", "？", "　"};
+      int skipped = 0;
+      for (size_t j = 0; j < sizeof(marks)/sizeof(marks[0]); j++)
+        {
+          size_t n = strlen(marks[j]);
+          if (bytes - i >= n && !memcmp(text + i, marks[j], n))
+            { i += n; skipped = 1; break; }
+        }
+      if (skipped) continue;
+      if (used == sizeof(normalized) - 1) return 0;
+      normalized[used++] = (c >= 'A' && c <= 'Z') ? (char)(c + 32) : (char)c;
+      i++;
+    }
+  normalized[used] = 0;
+  return !strcmp(normalized, "你好") || !strcmp(normalized, "你好呀") ||
+         !strcmp(normalized, "你好啊") || !strcmp(normalized, "你好openvela") ||
+         !strcmp(normalized, "openvela你好");
+}
+#endif
